INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Dient die Leistungsabrechnung dazu, interne Leistungen zwischen Abteilungen abzurechnen?', 2, '[{"text": "Ja", "correct": true, "because": "Hauptzweck der Leistungsabrechnung"}, {"text": "Nein", "correct": false, "because": "Interne Abrechnung ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Leistungsabrechnung auch externe Kunden betreffen?', 2, '[{"text": "Ja", "correct": false, "because": "Sie ist primär intern"}, {"text": "Nein", "correct": true, "because": "Fokus auf interne Verrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird die Leistungsabrechnung genutzt, um die Kostenstellen transparenter zu machen?', 2, '[{"text": "Ja", "correct": true, "because": "Erhöht Kostentransparenz"}, {"text": "Nein", "correct": false, "because": "Transparenz ist ein Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Leistungsabrechnung immer echte Geldflüsse stattfinden?', 2, '[{"text": "Ja", "correct": false, "because": "Interne Verrechnung ist oft rein rechnerisch"}, {"text": "Nein", "correct": true, "because": "Rechnerische Abrechnung reicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Leistungsabrechnung die Produktkalkulation beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Kostenverursachung wird klarer"}, {"text": "Nein", "correct": false, "because": "Indirekter Einfluss gegeben"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Leistungsabrechnung?', 2, '[{"text": "Verrechnung interner Leistungen", "correct": true, "because": "Kern der Leistungsabrechnung"}, {"text": "Festlegung externer Preise", "correct": false, "because": "Nicht primär"}, {"text": "Berechnung der Fixkosten", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten werden in der Leistungsabrechnung typischerweise verrechnet?', 3, '[{"text": "Gemeinkosten", "correct": true, "because": "Häufig intern verteilt"}, {"text": "Direkte Materialkosten", "correct": false, "because": "Einzelkosten, nicht primär"}, {"text": "Variable Kosten", "correct": false, "because": "Nur teilweise relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird oft für die Leistungsabrechnung verwendet?', 2, '[{"text": "Verrechnungssätze", "correct": true, "because": "Übliche Praxis"}, {"text": "Direkte Zahlungen", "correct": false, "because": "Nicht intern üblich"}, {"text": "Pauschalzuweisung", "correct": false, "because": "Weniger genau"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn die Leistungsabrechnung nicht durchgeführt wird?', 3, '[{"text": "Kostenverursachung bleibt unklar", "correct": true, "because": "Transparenz fehlt"}, {"text": "Einzelkosten steigen", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Gewinne sinken", "correct": false, "because": "Indirekt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Basis wird für die Leistungsabrechnung häufig genutzt?', 2, '[{"text": "Kostenstellen", "correct": true, "because": "Grundlage der Verrechnung"}, {"text": "Produktmengen", "correct": false, "because": "Weniger üblich"}, {"text": "Umsatzerlöse", "correct": false, "because": "Kein direkter Bezug"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Ziele verfolgt die Leistungsabrechnung?', 4, '[{"text": "Kostentransparenz erhöhen", "correct": true, "because": "Hauptvorteil"}, {"text": "Interne Leistungen verrechnen", "correct": true, "because": "Kernaufgabe"}, {"text": "Externe Rechnungen erstellen", "correct": false, "because": "Nicht primär"}, {"text": "Kostenverursachung klären", "correct": true, "because": "Verursacherprinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche werden in der Leistungsabrechnung typischerweise einbezogen?', 3, '[{"text": "Produktionsabteilung", "correct": true, "because": "Leistungserbringer"}, {"text": "Verwaltung", "correct": true, "because": "Leistungsempfänger möglich"}, {"text": "Kundendienst", "correct": true, "because": "Interne Leistungen"}, {"text": "Externe Partner", "correct": false, "because": "Intern fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Leistungsabrechnung?', 4, '[{"text": "Bessere Kostenkontrolle", "correct": true, "because": "Überwachung möglich"}, {"text": "Klarheit über Kostenverursachung", "correct": true, "because": "Transparenz"}, {"text": "Senkung der Einzelkosten", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Genauere Produktkalkulation", "correct": true, "because": "Indirekter Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für die Leistungsabrechnung wichtig?', 3, '[{"text": "Kostenstellen", "correct": true, "because": "Verrechnungsgrundlage"}, {"text": "Verrechnungssätze", "correct": true, "because": "Bestimmen Höhe"}, {"text": "Verkaufspreise", "correct": false, "because": "Folge, nicht Basis"}, {"text": "Leistungsmengen", "correct": true, "because": "Mengenabhängigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten können in der Leistungsabrechnung verrechnet werden?', 3, '[{"text": "Gemeinkosten", "correct": true, "because": "Häufig verteilt"}, {"text": "Personalkosten für interne Leistungen", "correct": true, "because": "Relevante Kosten"}, {"text": "Direkte Materialkosten", "correct": false, "because": "Einzelkosten"}, {"text": "Abschreibungen", "correct": true, "because": "Teil der Gemeinkosten"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Leistungsabrechnung verrechnet interne Leistungen. b) Sie betrifft externe Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (intern)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Leistungsabrechnung erhöht die Kostentransparenz. b) Sie erfordert echte Geldflüsse.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (rechnerisch)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kostenstellen sind Basis der Leistungsabrechnung. b) Sie dient nur der Gewinnberechnung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Verrechnung)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Verrechnungssätze sind Teil der Leistungsabrechnung. b) Sie beeinflusst die Produktkalkulation nicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (indirekter Einfluss)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Leistungsabrechnung klärt die Kostenverursachung. b) Sie ist ein Werkzeug der Leistungsrechnung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Verursachung, b) Leistungsrechnung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
